def _sv_paldea_dex_entries() -> list[tuple[int, str]]:
    entries: list[tuple[int, str]] = []
    for match in re.finditer(r"#\s*(\d+)\s+(.+?)(?=(?:【\d+†)?#\s*\d+\s|$)", _SV_PALDEA_DEX_RAW):
        entries.append((int(match.group(1)), match.group(2).strip()))
    return entries


