def _generic_entries_for_game(game: dict[str, Any]) -> list[dict[str, Any]]:
    if game["id"] == "legends-za":
        entries = []
        seen_dex = set()
        for lumiose_number, name in enumerate(_ZA_LUMIOSE_DEX_NAMES, start=1):
            row = _ALL_POKEMON_BY_NAME.get(name.replace("-", "").replace("'", "").lower())
            if not row or row[0] in seen_dex:
                continue
            dex, seed_name, type1, type2 = row
            entries.append({
                "dex": dex,
                "regional_dex": lumiose_number,
                "name": _sprite_name(seed_name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": "Lumiose Pokédex draft",
                "note": "Main-game Z-A Lumiose Pokédex draft entry. DLC/Hyperspace additions are intentionally excluded here.",
                **_sprite_fields(dex, game["id"]),
            })
            seen_dex.add(dex)
        _apply_za_location_data(entries)
        return entries

    if game["id"] == "heartgold-soulsilver":
        rows_by_name = {_pokemon_name_key(row[1]): row for rows in (KANTO, JOHTO, SINNOH) for row in rows}
        updated_johto = [
            rows_by_name[_pokemon_name_key(name)]
            for name in _HGSS_JOHTO_DEX_NAMES
            if _pokemon_name_key(name) in rows_by_name
        ]
        entries = []
        for regional_dex, (dex, name, type1, type2) in enumerate(updated_johto, start=1):
            types = [type1] + ([type2] if type2 else [])
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": types,
                "method": "HG/SS updated Johto dex draft",
                "note": (
                    "V2 HG/SS entry for updated Johto-dex coverage. Route-perfect encounter rates, Safari blocks, "
                    "and version blockers are being layered in from the guide pass."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
        _apply_hgss_rules(entries)
        return entries

    if game["id"] == "scarlet-violet":
        entries = []
        seen_dex = set()
        for regional_dex, raw_name in _SV_PALDEA_DEX_ENTRIES:
            override = _SV_PALDEA_NAME_OVERRIDES.get(_pokemon_name_key(raw_name))
            lookup_name = override[0] if override else raw_name
            display_name = override[1] if override else raw_name
            row = _ALL_POKEMON_BY_NAME.get(_pokemon_name_key(lookup_name))
            if not row or row[0] in seen_dex:
                continue
            dex, _, type1, type2 = row
            if dex == 194:
                type1, type2 = "poison", "ground"
            elif dex == 128:
                type1, type2 = "fighting", None
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": display_name,
                "types": [type1] + ([type2] if type2 else []),
                "method": "Paldea regional dex draft",
                "note": (
                    "Base-game Paldea regional dex draft entry for Scarlet/Violet. DLC dexes stay excluded here "
                    "while route, province, Titan, and Area Zero detail gets layered in."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
            seen_dex.add(dex)
        return entries

    if game["id"] in {"ruby-sapphire", "emerald", "oras"}:
        entries = []
        for regional_dex, (dex, name, type1, type2) in enumerate(HOENN, start=1):
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": f"{game['name']} Hoenn dex draft",
                "note": (
                    f"Hoenn regional dex draft entry for {game['name']}. Keep regional numbering visible until the "
                    "National Dex or postgame cleanup becomes relevant, then use the Nat # note for cross-game context."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
        return entries

    if game["id"] in {"red-blue", "yellow", "lets-go"}:
        entries = []
        for regional_dex, (dex, name, type1, type2) in enumerate(KANTO, start=1):
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": f"{game['name']} Kanto dex draft",
                "note": (
                    f"Kanto regional dex draft entry for {game['name']}. Keep regional numbering visible until the "
                    "National Dex or postgame cleanup becomes relevant, then use the Nat # note for cross-game context."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
        return entries

    if game["id"] in {"gold-silver", "crystal"}:
        entries = []
        for regional_dex, (dex, name, type1, type2) in enumerate(JOHTO, start=1):
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": f"{game['name']} Johto dex draft",
                "note": (
                    f"Johto regional dex draft entry for {game['name']}. Keep regional numbering visible until the "
                    "Kanto half or postgame cleanup becomes relevant, then use the Nat # note for cross-game context."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
        return entries

    if game["id"] in {"diamond-pearl", "platinum", "bdsp"}:
        sinnoh_names = _EXTENDED_SINNOH_DEX_NAMES if game["id"] == "platinum" else _ORIGINAL_SINNOH_DEX_NAMES
        entries = []
        seen_dex = set()
        for regional_dex, raw_name in enumerate(sinnoh_names, start=1):
            row = _ALL_POKEMON_BY_NAME.get(_pokemon_name_key(raw_name))
            if not row or row[0] in seen_dex:
                continue
            dex, name, type1, type2 = row
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": (
                    "Platinum extended Sinnoh dex draft"
                    if game["id"] == "platinum"
                    else f"{game['name']} original Sinnoh dex draft"
                ),
                "note": (
                    f"{game['name']} regional dex draft entry. Keep regional numbering visible until the "
                    "National Dex or postgame cleanup becomes relevant, then use the Nat # note for cross-game context."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
            seen_dex.add(dex)
        return entries

    if game["id"] in {"black-white", "black2-white2"}:
        entries = []
        for dex, name, type1, type2 in UNOVA:
            regional_dex = 0 if dex == 494 else dex - 494
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": f"{game['name']} Unova dex draft",
                "note": (
                    f"Unova regional dex draft entry for {game['name']}. Victini stays at regional #000, then the main run "
                    "starts at #001 Snivy until the National Dex or postgame cleanup becomes relevant."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
        return entries

    if game["id"] == "x-y":
        entries = []
        for regional_dex, (dex, name, type1, type2) in enumerate(KALOS, start=1):
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": f"{game['name']} Kalos dex draft",
                "note": (
                    f"Kalos regional dex draft entry for {game['name']}. Keep regional numbering visible until the "
                    "National Dex or postgame cleanup becomes relevant, then use the Nat # note for cross-game context."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
        return entries

    if game["id"] in {"sun-moon", "usum"}:
        entries = []
        for regional_dex, (dex, name, type1, type2) in enumerate(ALOLA, start=1):
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": f"{game['name']} Alola dex draft",
                "note": (
                    f"Alola regional dex draft entry for {game['name']}. Keep regional numbering visible until the "
                    "National Dex or postgame cleanup becomes relevant, then use the Nat # note for cross-game context."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
        return entries

    if game["id"] == "sword-shield":
        entries = []
        for regional_dex, (dex, name, type1, type2) in enumerate(GALAR, start=1):
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": f"{game['name']} Galar dex draft",
                "note": (
                    f"Galar regional dex draft entry for {game['name']}. Keep regional numbering visible until the "
                    "National Dex or DLC-aware postgame cleanup becomes relevant, then use the Nat # note for cross-game context."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
        return entries

    if game["id"] == "legends-arceus":
        entries = []
        seen_dex = set()
        regional_dex = 1
        for dex, name, type1, type2 in _REGION_DEX["Hisui"]:
            if dex in seen_dex:
                continue
            entries.append({
                "dex": dex,
                "regional_dex": regional_dex,
                "name": _sprite_name(name).title().replace("-", " "),
                "types": [type1] + ([type2] if type2 else []),
                "method": f"{game['name']} Hisui field index draft",
                "note": (
                    f"Hisui field-index draft entry for {game['name']}. Keep this regional-style numbering visible until "
                    "late postgame or cross-region National Dex comparisons become relevant."
                ),
                "tags": [],
                **_sprite_fields(dex, game["id"]),
            })
            seen_dex.add(dex)
            regional_dex += 1
        for dex in _GAME_STARTERS.get(game["id"], []):
            if dex in seen_dex:
                continue
            starter = _entry_from_dex(dex, game)
            if starter:
                starter.update({
                    "regional_dex": regional_dex,
                    "method": f"{game['name']} starter choice",
                    "note": (
                        f"Starter choice for {game['name']} added to this Hisui field-index draft so the opening roster stays "
                        "visible alongside the broader regional survey order."
                    ),
                })
                entries.insert(0, starter)
                regional_dex += 1
        for index, entry in enumerate(entries, start=1):
            entry["regional_dex"] = index
        return entries

    seed_rows = _REGION_DEX.get(game.get("region"), KANTO)
    entries = []
    for dex, name, type1, type2 in seed_rows:
        types = [type1] + ([type2] if type2 else [])
        entries.append({
            "dex": dex,
            "name": _sprite_name(name).title().replace("-", " "),
            "types": types,
            "method": f"{game['region']} guide dex draft",
            "note": (
                f"V2 guide-draft entry for {game['name']}. This is usable for caught tracking now; "
                "route-perfect guide and version-lock data still need to be layered in."
            ),
            **_sprite_fields(dex, game["id"]),
        })
    existing_dex = {entry["dex"] for entry in entries}
    for dex in _GAME_STARTERS.get(game["id"], []):
        if dex in existing_dex:
            continue
        starter = _entry_from_dex(dex, game)
        if starter:
            starter.update({
                "method": f"{game['name']} starter choice",
                "note": (
                    f"Starter choice for {game['name']} added to this V2 guide draft even though it is not "
                    f"part of the base {game['region']} seed list."
                ),
            })
            entries.insert(0, starter)
            existing_dex.add(dex)
    return entries


def _entry_from_dex(dex: int, game: dict[str, Any]) -> dict[str, Any] | None:
    row = _ALL_POKEMON.get(dex)
    if not row:
        return None
    dex_number, name, type1, type2 = row
    return {
        "dex": dex_number,
        "name": _sprite_name(name).title().replace("-", " "),
        "types": [type1] + ([type2] if type2 else []),
        "method": f"{game['name']} starter/special choice",
        "note": f"Game-specific V2 starter/special choice for {game['name']}.",
        **_sprite_fields(dex_number, game["id"]),
    }


def _za_key(name: str) -> str:
    return name.replace("-", "").replace("'", "").replace("é", "e").lower()


def _pokemon_name_key(name: str) -> str:
    return (
        name.replace("-", "")
        .replace("'", "")
        .replace(".", "")
        .replace(" ", "")
        .replace("é", "e")
        .replace("♀", "f")
        .replace("♂", "m")
        .lower()
    )


def _apply_za_location_data(entries: list[dict[str, Any]]) -> None:
    zone_map: dict[str, list[dict[str, str]]] = {}
    for zone in _ZA_WILD_ZONES:
        for name in zone["pokemon"]:
            zone_map.setdefault(_za_key(name), []).append(zone)

    for entry in entries:
        key = _za_key(entry["name"])
        zones = zone_map.get(key, [])
        if zones:
            zone_labels = ", ".join(zone["zone"] for zone in zones)
            unlocks = "; ".join(f"{zone['zone']}: {zone['unlock']} ({zone['levels']})" for zone in zones)
            entry["method"] = zone_labels
            entry["note"] = f"Confirmed Lumiose Wild Zone listing. {unlocks}."
            entry["wild_zones"] = [zone["zone"] for zone in zones]
            entry["wild_zone_unlocks"] = unlocks
            entry["tags"] = sorted(set(entry.get("tags", []) + ["wild-zone"]))
            continue

        special = _ZA_SPECIAL_METHODS.get(entry["name"])
        if special:
            method, note = special
            mega_note = _ZA_MEGA_SOURCE_NOTES.get(entry["name"])
            if mega_note:
                note = f"{note} Mega source note: {mega_note}"
            entry["method"] = method
            entry["note"] = note
            special_tags = ["special"]
            special_blob = f"{method} {note}".lower()
            if "postgame" in special_blob:
                special_tags.append("postgame")
            if "mystery gift" in special_blob:
                special_tags.append("mystery-gift")
            if mega_note:
                special_tags.extend(["mega-planning", "mega-source-review"])
            entry["tags"] = sorted(set(entry.get("tags", []) + special_tags))
            continue

        evolves_from = _ZA_EVOLVE_FROM.get(entry["name"])
        if evolves_from:
            exact_method = _ZA_EVOLUTION_METHODS.get(entry["name"])
            if exact_method:
                method, note, extra_tags = exact_method
                entry["method"] = method
                entry["note"] = note
                entry["tags"] = sorted(set(entry.get("tags", []) + ["evolution", *extra_tags]))
            else:
                entry["method"] = f"Evolve {evolves_from}"
                entry["note"] = (
                    f"Evolution target from {evolves_from}. Exact level, item, time, move, trade, or form requirement "
                    "should be checked in your save before final guide copy."
                )
                entry["tags"] = sorted(set(entry.get("tags", []) + ["evolution"]))

        mega_note = _ZA_MEGA_SOURCE_NOTES.get(entry["name"])
        if mega_note:
            existing_note = entry.get("note", "")
            entry["note"] = f"{existing_note} Mega source note: {mega_note}".strip()
            mega_tags = ["mega-planning", "mega-source-review"]
            if "dlc" in mega_note.lower() or "postgame" in mega_note.lower() or "mega dimension" in mega_note.lower():
                mega_tags.append("postgame")
            entry["tags"] = sorted(set(entry.get("tags", []) + mega_tags))


def _apply_hgss_rules(entries: list[dict[str, Any]]) -> None:
    for entry in entries:
        dex = entry["dex"]
        tags = set(entry.get("tags", []))
        notes = []
        if dex in _HGSS_HEARTGOLD_EXCLUSIVE:
            tags.update({"version-exclusive", "heartgold-exclusive"})
            notes.append("HeartGold-focused version exclusive or version-linked legendary; SoulSilver needs trade/paired-version handling.")
        if dex in _HGSS_SOULSILVER_EXCLUSIVE:
            tags.update({"version-exclusive", "soulsilver-exclusive"})
            notes.append("SoulSilver-focused version exclusive or version-linked legendary; HeartGold needs trade/paired-version handling.")
        if dex in _HGSS_DAY_NIGHT:
            tags.add("day-night")
            entry["hgss_time"] = _HGSS_DAY_NIGHT[dex]
            notes.append(f"Time-of-day reminder: {_HGSS_DAY_NIGHT[dex]}.")
        if dex in {190, 204, 214}:
            tags.add("headbutt")
            notes.append("Headbutt tree reminder; use the Headbutt filter/dashboard while refining exact tree data.")
        if dex in {48, 123, 127}:
            tags.add("contest")
            notes.append("Bug-Catching Contest or National Park-style reminder.")
        if dex in _HGSS_STATIC_GIFT:
            tags.update({"gift-static", "guide-target"})
            notes.append(_HGSS_STATIC_GIFT[dex])
        if dex in _HGSS_LEGENDARY_EVENT:
            tags.add("legendary")
            if dex == 251:
                tags.add("event-only")
            notes.append(_HGSS_LEGENDARY_EVENT[dex])
        if notes:
            entry["note"] = f"{entry.get('note', '')} HG/SS note: {' '.join(notes)}".strip()
            if "HG/SS updated Johto dex draft" in entry.get("method", ""):
                entry["method"] = "HG/SS special/version-aware target"
        entry["tags"] = sorted(tags)


def _starter_entries_for_game(game: dict[str, Any], entries: list[dict[str, Any]]) -> list[dict[str, Any]]:
    by_dex = {entry["dex"]: entry for entry in entries}
    starters = []
    for dex in _GAME_STARTERS.get(game["id"], []):
        starter = by_dex.get(dex) or _entry_from_dex(dex, game)
        if starter:
            starters.append(starter)
    if starters:
        return starters
    return [entry for index, entry in enumerate(entries[:9]) if index in {0, 3, 6}]


