def _starter_profiles_for_game(game: dict[str, Any], starters: list[dict[str, Any]]) -> list[dict[str, Any]]:
    profile_map = _GAME_STARTER_PROFILES.get(game["id"], {})
    profiles = []
    for starter in starters:
        profile = profile_map.get(starter["dex"])
        if not profile:
            continue
        profiles.append(
            {
                "dex": starter["dex"],
                "name": starter["name"],
                "pros": profile["pros"],
                "cons": profile["cons"],
                "role": profile.get("role", ""),
                "strategy": profile.get("strategy", ""),
                "picks": list(profile.get("picks", [])),
                "team_title": profile.get("team_title", ""),
                "team_summary": profile.get("team_summary", ""),
                "team_route": list(profile.get("team_route", [])),
                "team_targets": list(profile.get("team_targets", [])),
                "sources": list(profile.get("sources", [])),
            }
        )
    return profiles


def _profile_for_game(game: dict[str, Any]) -> dict[str, Any]:
    fallback = {
        "guide_focus": f"{game['name']} needs a game-specific guide pass for routes, items, version locks, gifts, trades, and postgame unlocks.",
        "mechanics": [f"{game['region']} guide dex", f"Generation {game['gen']} type rules", "Exact route data pending"],
    }
    return {**fallback, **_GAME_PROFILES.get(game["id"], {})}


def _theme_for_game(game: dict[str, Any]) -> dict[str, Any]:
    family = _GAME_THEME_FAMILIES.get(game["id"], "default")
    copy = _GAME_THEME_COPY.get(family, _DEFAULT_THEME_COPY)
    return {
        "family": family,
        **copy,
    }


def _guide_target_from_entry(entry: dict[str, Any], where: str, when: str, why: str) -> dict[str, Any]:
    return {
        "dex": entry["dex"],
        "name": entry["name"],
        "where": where,
        "when": when,
        "why_it_matters": why,
    }


def _slice_targets(entries: list[dict[str, Any]], start: int, stop: int, where: str, when: str, why: str) -> list[dict[str, Any]]:
    return [
        _guide_target_from_entry(entry, where, when, why)
        for entry in entries[start:stop]
    ]


def _with_review_prompt(chapter: dict[str, Any]) -> dict[str, Any]:
    """Keep catch tracking on target cards, not in the guide checklist."""
    steps = [
        step
        for step in chapter.get("guide_steps", [])
        if step.get("category") != "catch"
    ]
    if chapter.get("pokemon_targets"):
        steps.append({
            "id": f"{chapter['id']}-review-targets",
            "label": "Review Pokémon available in this area",
            "detail": "Scroll to the catch targets below, then use those Pokémon cards or the Pokédex to mark what you actually caught.",
            "category": "review",
        })
    return {**chapter, "guide_steps": steps}


def _za_target(dex: int, name: str, where: str, when: str, why: str, *, method: str, rarity: str = "Confirmed / verify in run", levels: str = "TBD", timing: str = "TBD", confidence: str = "Verify in save", tip: str = "") -> dict[str, Any]:
    return {
        "dex": dex,
        "name": name,
        "where": where,
        "when": when,
        "why_it_matters": why,
        "method": method,
        "rarity": rarity,
        "levels": levels,
        "timing": timing,
        "confidence": confidence,
        "tip": tip or "Use this as a confirmed planning target, then refine exact location/timing as you verify it in your save.",
        **_sprite_fields(dex, "legends-za"),
    }


def _za_promotion_fight(
    name: str,
    rank: str,
    *,
    team: list[str],
    counters: list[str],
    strategy: str,
    ticket_points: int | None = None,
) -> dict[str, Any]:
    fight = {
        "name": name,
        "rank": rank,
        "team": team,
        "counters": counters,
        "strategy": strategy,
    }
    if ticket_points is not None:
        fight["ticket_points"] = f"{ticket_points:,} Ticket Points"
    return fight


