def _hgss_target(dex: int, name: str, where: str, when: str, why: str, *, method: str, rarity: str = "Route target", levels: str = "Route range", timing: str = "Any", confidence: str = "Guide draft", tip: str = "", version: str = "both", time_of_day: str = "any") -> dict[str, Any]:
    return {
        "dex": dex,
        "name": name,
        "where": where,
        "when": when,
        "why_it_matters": why,
        "method": method,
        "rarity": rarity,
        "levels": levels,
        "timing": timing,
        "confidence": confidence,
        "version_availability": version,
        "time_of_day": time_of_day,
        "tip": tip or "Use this as a playthrough catch/reminder target; refine exact rates if your save disagrees.",
        **_sprite_fields(dex, "heartgold-soulsilver"),
    }


