def _oras_target(
    dex: int,
    name: str,
    where: str,
    when: str,
    why: str,
    *,
    method: str,
    rarity: str = "Route target",
    levels: str = "Route range",
    timing: str = "Any",
    confidence: str = "Guide draft",
    tip: str = "",
    version: str = "both",
    tags: list[str] | None = None,
) -> dict[str, Any]:
    return {
        "dex": dex,
        "name": name,
        "where": where,
        "when": when,
        "why_it_matters": why,
        "method": method,
        "rarity": rarity,
        "levels": levels,
        "timing": timing,
        "confidence": confidence,
        "version_availability": version,
        "tip": tip or "Use this as an ORAS playthrough target and tighten route-perfect remake details later if needed.",
        "tags": tags or [],
        **_sprite_fields(dex, "oras"),
    }


