def _platinum_target(
    dex: int,
    name: str,
    where: str,
    when: str,
    why: str,
    *,
    method: str,
    rarity: str = "Route target",
    levels: str = "Route range",
    timing: str = "Any",
    confidence: str = "Guide draft",
    tip: str = "",
    tags: list[str] | None = None,
) -> dict[str, Any]:
    return {
        "dex": dex,
        "name": name,
        "where": where,
        "when": when,
        "why_it_matters": why,
        "method": method,
        "rarity": rarity,
        "levels": levels,
        "timing": timing,
        "confidence": confidence,
        "tip": tip or "Use this as a Platinum playthrough target and tighten exact tables later if needed.",
        "tags": tags or [],
        **_sprite_fields(dex, "platinum"),
    }


def _diamond_pearl_target(
    dex: int,
    name: str,
    where: str,
    when: str,
    why: str,
    *,
    method: str,
    rarity: str = "Route target",
    levels: str = "Route range",
    timing: str = "Any",
    confidence: str = "Guide draft",
    tip: str = "",
    version: str = "both",
    tags: list[str] | None = None,
) -> dict[str, Any]:
    return {
        "dex": dex,
        "name": name,
        "where": where,
        "when": when,
        "why_it_matters": why,
        "method": method,
        "rarity": rarity,
        "levels": levels,
        "timing": timing,
        "confidence": confidence,
        "version_availability": version,
        "tip": tip or "Use this as a Diamond/Pearl playthrough target and tighten exact route tables later if needed.",
        "tags": tags or [],
        **_sprite_fields(dex, "diamond-pearl"),
    }


