def _platinum_target_matches_ref(target: dict[str, Any], ref: int | tuple[int, str]) -> bool:
    if isinstance(ref, int):
        return target.get("dex") == ref
    dex, where_fragment = ref
    return target.get("dex") == dex and where_fragment.lower() in str(target.get("where", "")).lower()


def _expand_platinum_guide(chapters: list[dict[str, Any]], guide_items: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    chapter_map = {chapter["id"]: chapter for chapter in chapters}
    steps_by_source = {chapter["id"]: list(chapter.get("guide_steps", [])) for chapter in chapters}
    targets_by_source = {chapter["id"]: list(chapter.get("pokemon_targets", [])) for chapter in chapters}
    items_by_id = {item["id"]: item for item in guide_items}
    source_sections: dict[str, list[dict[str, Any]]] = {}
    used_steps: set[str] = set()
    used_items: set[str] = set()
    used_targets: set[tuple[str, int, str]] = set()
    expanded: list[dict[str, Any]] = []

    for spec in _PLATINUM_SECTION_SPECS:
        source = spec["source"]
        parent = chapter_map[source]
        source_sections.setdefault(source, [])
        step_lookup = {step["id"]: step for step in steps_by_source[source]}
        chapter_steps = [dict(step_lookup[step_id]) for step_id in spec.get("step_ids", []) if step_id in step_lookup]
        used_steps.update(step["id"] for step in chapter_steps)
        chapter_steps.extend(dict(step) for step in spec.get("extra_steps", []))

        chapter_targets: list[dict[str, Any]] = []
        target_sources = spec.get("target_sources", [source])
        for ref in spec.get("target_refs", []):
            for target_source in target_sources:
                for target in targets_by_source.get(target_source, []):
                    marker = (target_source, target.get("dex", 0), str(target.get("where", "")))
                    if marker in used_targets:
                        continue
                    if _platinum_target_matches_ref(target, ref):
                        chapter_targets.append(dict(target))
                        used_targets.add(marker)
                        break
                else:
                    continue
                break

        include_boss = spec.get("include_boss", False) and parent.get("boss")
        chapter = {
            "id": spec["id"],
            "title": spec["title"],
            "stage": parent.get("stage", ""),
            "subtitle": spec.get("subtitle") or parent.get("subtitle", ""),
            "guide_steps": chapter_steps,
            "pokemon_targets": chapter_targets,
        }
        for passthrough_key in ("primary_goal", "strategy_callout", "secrets_callout"):
            if spec.get(passthrough_key):
                chapter[passthrough_key] = dict(spec[passthrough_key])
        if spec.get("checkpoint_callout"):
            chapter["checkpoint_callout"] = dict(spec["checkpoint_callout"])
        if include_boss:
            chapter["boss"] = dict(parent["boss"])
        expanded.append(chapter)
        source_sections[source].append(chapter)

        for item_id in spec.get("item_ids", []):
            item = items_by_id.get(item_id)
            if not item:
                continue
            item["chapter_id"] = spec["id"]
            item["chapter"] = spec["title"]
            used_items.add(item_id)

    for source, parent in chapter_map.items():
        fallback = source_sections.get(source, [])
        if not fallback:
            continue
        catchall = fallback[-1]
        existing_step_ids = {step["id"] for step in catchall.get("guide_steps", [])}
        for step in steps_by_source[source]:
            if step["id"] not in used_steps and step["id"] not in existing_step_ids:
                catchall.setdefault("guide_steps", []).append(dict(step))
                used_steps.add(step["id"])
        existing_target_markers = {(target.get("dex", 0), str(target.get("where", ""))) for target in catchall.get("pokemon_targets", [])}
        for target in targets_by_source[source]:
            marker = (source, target.get("dex", 0), str(target.get("where", "")))
            if marker not in used_targets and (target.get("dex", 0), str(target.get("where", ""))) not in existing_target_markers:
                catchall.setdefault("pokemon_targets", []).append(dict(target))
                used_targets.add(marker)
        for item in guide_items:
            if item["chapter_id"] == source and item["id"] not in used_items:
                item["chapter_id"] = catchall["id"]
                item["chapter"] = catchall["title"]
                used_items.add(item["id"])

    for chapter in expanded:
        if not chapter.get("pokemon_targets"):
            chapter["guide_steps"] = [
                step for step in chapter.get("guide_steps", [])
                if not str(step.get("id", "")).endswith("-review-targets")
            ]

    return expanded, guide_items


def _guide_nav_groups(game: dict[str, Any], chapters: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if game["id"] != "platinum":
        return []

    chapter_map = {chapter["id"]: chapter for chapter in chapters}
    groups: list[dict[str, Any]] = []
    for group in _PLATINUM_NAV_GROUPS:
        group_chapters = [chapter_map[chapter_id] for chapter_id in group["chapter_ids"] if chapter_id in chapter_map]
        if not group_chapters:
            continue
        groups.append({
            "id": group["id"],
            "label": group["label"],
            "summary": group["summary"],
            "chapters": group_chapters,
        })
    return groups


def _bw_target(
    dex: int,
    name: str,
    where: str,
    when: str,
    why: str,
    *,
    method: str,
    rarity: str = "Route target",
    levels: str = "Route range",
    timing: str = "Any",
    confidence: str = "Guide draft",
    tip: str = "",
    version: str = "both",
    tags: list[str] | None = None,
) -> dict[str, Any]:
    return {
        "dex": dex,
        "name": name,
        "where": where,
        "when": when,
        "why_it_matters": why,
        "method": method,
        "rarity": rarity,
        "levels": levels,
        "timing": timing,
        "confidence": confidence,
        "version_availability": version,
        "tip": tip or "Use this as a Black/White playthrough target and tighten encounter-table details later if needed.",
        "tags": tags or [],
        **_sprite_fields(dex, "black-white"),
    }


