def _pla_target(
    dex: int,
    name: str,
    where: str,
    when: str,
    why: str,
    *,
    method: str,
    rarity: str = "Research target",
    levels: str = "Area range",
    timing: str = "Any",
    confidence: str = "Guide draft",
    tip: str = "",
    tags: list[str] | None = None,
) -> dict[str, Any]:
    return {
        "dex": dex,
        "name": name,
        "where": where,
        "when": when,
        "why_it_matters": why,
        "method": method,
        "rarity": rarity,
        "levels": levels,
        "timing": timing,
        "confidence": confidence,
        "version_availability": "both",
        "tip": tip or "Use this as a Legends: Arceus research target and tighten exact spawn/task details later if needed.",
        "tags": tags or [],
        **_sprite_fields(dex, "legends-arceus"),
    }


