def _gsc_target(dex: int, name: str, where: str, when: str, why: str, *, method: str, version: str = "both", tags: list[str] | None = None) -> dict[str, Any]:
    return {
        "dex": dex,
        "name": name,
        "where": where,
        "when": when,
        "why_it_matters": why,
        "method": method,
        "rarity": "Guide target",
        "levels": "Route range",
        "timing": when,
        "confidence": "Guide draft",
        "version_availability": version,
        "tip": "Use this as a Johto route reminder and tighten exact time/day tables later if needed.",
        "tags": tags or [],
        **_sprite_fields(dex, "gold-silver"),
    }


