    chapters[4]["pokemon_targets"] = [_gsc_target(245, "Suicune", "Crystal story route", "Mid-late Johto", "Crystal's signature legendary route and one of its biggest identity beats.", method="Story legendary", tags=["legendary", "gift-static"])]
    chapters[5]["pokemon_targets"][-2] = _gsc_target(249, "Lugia", "Whirl Islands", "Late Johto", "Crystal late legendary and a marquee Johto target.", method="Static legendary", tags=["legendary", "gift-static"])
