def _build_kanto_entries() -> list[dict[str, Any]]:
    entries = _base_kanto_entries()
    overrides = _entry_overrides()
    for entry in entries:
        dex = entry["dex"]
        if dex in _FR_EXCLUSIVE:
            entry["available_versions"] = ["firered"]
            entry["tags"] = sorted(set(entry["tags"] + ["version-exclusive"]))
        elif dex in _LG_EXCLUSIVE:
            entry["available_versions"] = ["leafgreen"]
            entry["tags"] = sorted(set(entry["tags"] + ["version-exclusive"]))

        if dex in _TRADE_EVOLUTIONS:
            entry.update({
                "status": "blocked",
                "obtainable": False,
                "method": "Trade evolution",
                "blocker": "Trade required",
                "tags": sorted(set(entry["tags"] + ["trade-evo"])),
                "requirements": sorted(set(entry["requirements"] + ["trade"])),
                "note": "Trade evolution. Enable trades in the V2 run rules to treat this as obtainable.",
            })
        if dex in _EVENT_ONLY:
            entry.update({
                "status": "blocked",
                "obtainable": False,
                "method": "Event distribution",
                "blocker": "Event only",
                "tags": sorted(set(entry["tags"] + ["event"])),
                "requirements": sorted(set(entry["requirements"] + ["event"])),
                "note": "Event-only target. Enable events in the V2 run rules to treat this as obtainable.",
            })
        if dex in _STARTER_LOCKED:
            entry.update({
                "status": "blocked",
                "obtainable": False,
                "blocker": "Starter locked",
                "tags": sorted(set(entry["tags"] + ["starter"])),
            })
        if dex in _FOSSIL_LOCKED:
            entry.update({
                "status": "blocked",
                "obtainable": False,
                "blocker": "Fossil choice",
                "tags": sorted(set(entry["tags"] + ["fossil"])),
            })
        if dex in overrides:
            merged = {**entry, **overrides[dex]}
            merged["tags"] = sorted(set(entry.get("tags", []) + overrides[dex].get("tags", [])))
            merged["requirements"] = sorted(set(entry.get("requirements", []) + overrides[dex].get("requirements", [])))
            entry.clear()
            entry.update(merged)
        if entry["method"] == "Kanto dex target" and dex in _KANTO_EVOLUTION_METHODS:
            method, note = _KANTO_EVOLUTION_METHODS[dex]
            entry["method"] = method
            entry["note"] = note
            tag = "evolution" if method.startswith(("Evolve", "Use ")) else "guide-needed"
            entry["tags"] = sorted(set(entry["tags"] + [tag]))
    return entries


def _target(
    dex: int,
    name: str,
    where: str,
    when: str,
    why_it_matters: str,
    version_note: str = "Available in both versions.",
    *,
    starter: str | None = None,
    versions: list[str] | None = None,
    kind: str = "catch",
    method: str | None = None,
    rarity: str | None = None,
    levels: str | None = None,
    timing: str | None = None,
    tip: str | None = None,
) -> dict[str, Any]:
    return {
        "dex": dex,
        "name": name,
        "where": where,
        "when": when,
        "why_it_matters": why_it_matters,
        "version_note": version_note,
        "starter": starter,
        "versions": versions or ["firered", "leafgreen"],
        "kind": kind,
        "method": method,
        "rarity": rarity,
        "levels": levels,
        "timing": timing,
        "tip": tip,
        **_sprite_fields(dex, "firered-leafgreen"),
    }


def v2_demo_context() -> dict[str, Any]:
    entries = _build_kanto_entries()

    counts = {
        "caught": sum(1 for e in entries if e["status"] == "caught"),
        "owned": sum(1 for e in entries if e["status"] in {"caught", "owned"}),
        "catchable": sum(1 for e in entries if e["status"] == "catchable"),
        "blocked": sum(1 for e in entries if e["status"] == "blocked"),
    }
    counts["tracked"] = len(entries) - counts["blocked"]
    counts["total"] = len(entries)
